{
  "schema_version": "existing-tests-extension-v2",
  "task_id": "bpmn-io__bpmn-js-2396",
  "status": "no_additional_tests_needed",
  "behavioral_contract": {
    "observable_requirements": [
      {
        "requirement_id": "constraint_001",
        "contract": "When connecting a sequence flow from a boundary event attached to an activity corner to a target element that is strictly axis-aligned (strictly above/below or strictly left/right of the target with no counter-axis offset), the layouter must produce a direct 2-waypoint straight connection docking at the boundary of the source and target elements without generating internal waypoints or loop-around maneuvers."
      }
    ],
    "preserved_behaviors": [
      "Sequence flow layouts for boundary events on non-corner edges (top/bottom/left/right center) remain unchanged.",
      "Sequence flow layouts for corner boundary events connecting to non-axis-aligned targets (requiring multi-segment routing) remain unchanged.",
      "Loop sequence flows and relayout behaviors for tasks, sub-processes, and gateways remain unchanged."
    ],
    "implementation_variation": "Any layout implementation that detects strict vertical or horizontal target orientation relative to corner boundary events and resolves to direct vertical ('v') or horizontal ('h') docking/routing paths is valid, regardless of whether it uses early return checks, helper functions, or unified vector alignment calculations in BpmnLayouter."
  },
  "coverage": [
    {
      "requirement_id": "constraint_001",
      "visual_category": "空间布局与几何理解",
      "coverage": "直接覆盖",
      "existing_test_ids": [
        "[[\"features/modeling - layout\",\"boundary events\",\"non-loops\"],\"should layout straight for axis-aligned corner boundary event\"]",
        "[[\"features/modeling - layout\",\"boundary events\",\"non-loops\"],\"should layout straight for horizontally axis-aligned corner boundary event\"]"
      ],
      "assertion_summary": "Directly asserts that connecting a corner boundary event to an axis-aligned target (both vertical and horizontal configurations) produces exactly a 2-point straight line with correct boundary docking coordinates without extra waypoints.",
      "reason": "The test suite already includes explicit unit tests with test fixtures covering both vertical and horizontal axis-aligned corner boundary event connections, directly measuring the exact docking endpoints and waypoint count."
    }
  ],
  "test_bundles": [],
  "oracle_quality_plan": {
    "status": "proposed_not_executed",
    "curator_only": true,
    "negative_variants": [
      {
        "variant_id": "omit_vertical_corner_axis_alignment_check",
        "defect_preserved_or_introduced": "Omits the vertical axis-alignment check in getBoundaryEventTargetLayout, reverting vertical corner connections to counter-axis corner comparison which adds invalid internal waypoints.",
        "expected_failure_test_ids": [
          "[[\"features/modeling - layout\",\"boundary events\",\"non-loops\"],\"should layout straight for axis-aligned corner boundary event\"]"
        ]
      },
      {
        "variant_id": "omit_horizontal_corner_axis_alignment_check",
        "defect_preserved_or_introduced": "Omits the horizontal axis-alignment check in getBoundaryEventTargetLayout, reverting horizontal corner connections to counter-axis corner comparison which adds invalid internal waypoints.",
        "expected_failure_test_ids": [
          "[[\"features/modeling - layout\",\"boundary events\",\"non-loops\"],\"should layout straight for horizontally axis-aligned corner boundary event\"]"
        ]
      }
    ],
    "equivalent_positive_variant": {
      "description": "An implementation that encapsulates the axis alignment check in a separate helper function (e.g., isStrictlyAligned) and returns 'v' or 'h' before falling back to corner orientation routing.",
      "expected_pass_test_ids": [
        "[[\"features/modeling - layout\",\"boundary events\",\"non-loops\"],\"should layout straight for axis-aligned corner boundary event\"]",
        "[[\"features/modeling - layout\",\"boundary events\",\"non-loops\"],\"should layout straight for horizontally axis-aligned corner boundary event\"]"
      ]
    }
  ],
  "missing_context": [],
  "summary": "Existing unit tests in LayoutSequenceFlowSpec.js directly and deterministically cover sequence flow straight routing for axis-aligned corner boundary events in both vertical and horizontal layouts, with verified F2P transition measurements. No additional tests are needed.",
  "human_review_required": false,
  "human_review_reasons": []
}

